H.background();
// Single-slit diffraction:  a * sin(theta) = m * lambda  (DARK fringes, m=±1,±2,…)
// Intensity:  I/I0 = (sin(beta)/beta)^2,  beta = pi * a * sin(theta) / lambda.
const v = H.plot2d({ xMin: -40, xMax: 40, yMin: 0, yMax: 1.2 });
v.grid(); v.axes();
const lam = P.lambda;   // wavelength (nm)
const a = P.a;          // slit width (micrometers)
const L = P.L;          // slit-to-screen distance (m)
const lam_m = lam * 1e-9, a_m = a * 1e-6, L_m = L;
function intensity(y_mm) {
  const y = y_mm * 1e-3;
  const theta = Math.atan2(y, L_m);
  const beta = Math.PI * a_m * Math.sin(theta) / lam_m;
  if (Math.abs(beta) < 1e-6) return 1;     // limit sinc^2 -> 1
  const s = Math.sin(beta) / beta;
  return s * s;
}
v.fn(intensity, { color: H.colors.accent, width: 2.5, steps: 500 });
// First-minimum position (mm): a sin(theta)=lambda -> y1 ~ lambda L / a.
const y1 = lam_m * L_m / a_m * 1e3;
for (let m = -3; m <= 3; m++) {
  if (m === 0) continue;
  const ym = m * y1;
  if (Math.abs(ym) <= 40) v.line(ym, 0, ym, 0.25, { color: H.colors.warn, width: 1, dash: [4, 4] });
}
